      <span className={`status status-${phase}`}>{phase === "ready" ? "Ready" : phase === "importing" ? "Importing" : phase === "capturing" ? "Analyzing" : phase === "complete" ? "Done" : "Draft"}</span>
    </header>

    <section className="source-section" aria-label="Page source">
      <label htmlFor="base-url">Base URL <span>optional — resolves relative assets when pasting HTML</span></label>
      <input id="base-url" value={baseUrl} placeholder="https://example.com/page/" onChange={(event) => { setBaseUrl(event.target.value); resetCapture(); }} />
      <label htmlFor="html-source">Page source <span>paste complete HTML or enter a full HTTP(S) URL</span></label>
      <textarea id="html-source" className="editor" value={source} spellCheck={false} aria-label="HTML source" placeholder="<!doctype html>\n<html>…</html>\n\n—or—\n\nhttps://example.com/page" onChange={(event) => { setSource(event.target.value); resetCapture(); }} />
    </section>

    <section className="viewport-section">
      <div className="section-heading"><h2>Responsive boards</h2><button className="text-button" onClick={() => { setViewports([...viewports, { id: crypto.randomUUID(), name: "Custom", width: 1024, height: 800 }]); resetCapture(); }}>Add viewport</button></div>
      <div className="viewport-list">
        {viewports.map((viewport) => <div className="viewport-row" key={viewport.id}>
          <input aria-label={`${viewport.name} name`} value={viewport.name} onChange={(event) => updateViewport(viewport.id, "name", event.target.value)} />
          <input aria-label={`${viewport.name} width`} type="number" min="1" value={viewport.width} onChange={(event) => updateViewport(viewport.id, "width", event.target.value)} />
          <span>×</span>
          <input aria-label={`${viewport.name} height`} type="number" min="1" value={viewport.height} onChange={(event) => updateViewport(viewport.id, "height", event.target.value)} />
          <button aria-label={`Remove ${viewport.name}`} className="icon-button" disabled={viewports.length === 1} onClick={() => { setViewports(viewports.filter((item) => item.id !== viewport.id)); resetCapture(); }}>×</button>
        </div>)}
      </div>
    </section>

    <section className="advanced-section">
      <button className="advanced-toggle" onClick={() => setAdvanced(!advanced)} aria-expanded={advanced}>Advanced capture {advanced ? "−" : "+"}</button>
      {advanced && <div className="advanced-panel">
        <label className="checkbox"><input type="checkbox" checked={scriptPolicy === "trusted"} onChange={(event) => { setScriptPolicy(event.target.checked ? "trusted" : "off"); resetCapture(); }} /> Run trusted page scripts <span>Off by default. Never use for untrusted HTML.</span></label>
        <label>Additional settle delay <output>{settleDelayMs}ms</output><input type="range" min="0" max="5000" step="100" value={settleDelayMs} onChange={(event) => { setSettleDelayMs(Number(event.target.value)); resetCapture(); }} /></label>
      </div>}
    </section>

    {scenes.length > 0 && <section className="analysis" aria-live="polite">
      <h2>Analysis</h2>
      <div className="summary"><strong>{warnings.layers.toLocaleString()}</strong> editable layers across {scenes.length} boards · {diagnostics.length} diagnostics</div>
      <ul>
        {scenes.map((scene) => <li key={scene.viewport.id}>{viewportLabel(scene.viewport)} — {scene.documentSize.width}×{Math.round(scene.documentSize.height)}px, {scene.nodes.length} layers</li>)}
        {diagnostics.slice(0, 4).map((diagnostic, index) => <li className="warning" key={`${diagnostic.code}-${index}`}>{diagnostic.message} {diagnostic.source ? `(${diagnostic.source})` : ""}</li>)}
        {diagnostics.length > 4 && <li className="warning">+ {diagnostics.length - 4} more diagnostics</li>}
      </ul>
    </section>}

    {error && <p className="error" role="alert">{error}</p>}
    {(phase === "capturing" || phase === "importing" || phase === "complete" || phase === "ready") && <p className="progress" aria-live="polite">{progress}</p>}
    <footer>
      {phase === "importing" ? <button className="secondary" onClick={cancel}>Cancel import</button> : <button className="secondary" onClick={analyze} disabled={phase === "capturing"}>Analyze page</button>}
      <button className="primary" onClick={importScenes} disabled={phase !== "ready"}>Import to Penpot</button>
    </footer>
  </main>;
}
import { utf8ByteLength } from "../shared/validation";

export interface ResolvedSource {
  html: string;
  baseUrl?: string;
  sourceUrl?: string;
}

const FETCH_PROXY_PATH = "/__html_to_penpot/fetch";
const MAX_INLINE_SVG_BYTES = 2 * 1024 * 1024;

function localFetchProxyUrl(target: string): string | undefined {
  const origin = typeof globalThis.location === "object" ? globalThis.location.origin : "";
  if (!origin || origin === "null") return undefined;
  return `${origin}${FETCH_PROXY_PATH}?url=${encodeURIComponent(target)}`;
}

function isSvgUrl(value: string): boolean {
  try {
    return new URL(value).pathname.toLowerCase().endsWith(".svg");
  } catch {
    return false;
  }
}

async function fetchAsset(url: string): Promise<Response | undefined> {
  try {
    const direct = await fetch(url, { credentials: "omit", redirect: "follow" });
    if (direct.ok) return direct;
  } catch {
    // The page host may not grant CORS; try the same local proxy used for the
    // source document when this is running from the development server.
  }
  const proxyUrl = localFetchProxyUrl(url);
  if (!proxyUrl) return undefined;
  try {
    const proxied = await fetch(proxyUrl, { credentials: "omit", redirect: "follow" });
    return proxied.ok ? proxied : undefined;
  } catch {
    return undefined;
  }
}

async function inlineSvgImages(html: string, baseUrl: string | undefined): Promise<string> {
  if (!baseUrl || typeof DOMParser === "undefined") return html;
  const document = new DOMParser().parseFromString(html, "text/html");
  const images = [...document.querySelectorAll("img[src]")];
  let changed = false;
  await Promise.all(images.map(async (image) => {
    const source = image.getAttribute("src");
    if (!source || source.startsWith("data:")) return;
    let target: URL;
    try { target = new URL(source, baseUrl); } catch { return; }
    if (!isSvgUrl(target.href)) return;
    const response = await fetchAsset(target.href);
    if (!response) return;
    const contentLength = Number(response.headers.get("content-length") || "0");
    if (contentLength > MAX_INLINE_SVG_BYTES) return;
    const svg = await response.text();
    if (utf8ByteLength(svg) > MAX_INLINE_SVG_BYTES || !/<svg[\s>]/i.test(svg)) return;
    image.setAttribute("src", `data:image/svg+xml,${encodeURIComponent(svg)}`);
    changed = true;
  }));
  return changed ? "<!doctype html>\n" + document.documentElement.outerHTML : html;
}

/** Return a web URL only when the complete source value is a URL. */
export function sourceUrl(value: string): string | undefined {
  const trimmed = value.trim();
  if (!trimmed) return undefined;
  if (/\s/.test(trimmed)) return undefined;
  try {
    const parsed = new URL(trimmed);
    return parsed.protocol === "http:" || parsed.protocol === "https:" ? parsed.href : undefined;
  } catch {
    return undefined;
  }
}

/**
 * Resolve the editor value into HTML. Pasted markup is returned unchanged;
 * a complete HTTP(S) URL is fetched so the browser can render the page itself.
 * The direct request is attempted first. If the target does not grant browser
 * CORS, the local development server proxy is used instead.
 */
export async function resolveSource(value: string, explicitBaseUrl?: string): Promise<ResolvedSource> {
  const url = sourceUrl(value);
  if (!url) return { html: await inlineSvgImages(value, explicitBaseUrl), baseUrl: explicitBaseUrl || undefined };

  let response: Response | undefined;
  let directError: unknown;
  try {
    response = await fetch(url, { credentials: "omit", redirect: "follow" });
  } catch (error) {
    directError = error;
  }

  if (!response) {
    const proxyUrl = localFetchProxyUrl(url);
    if (proxyUrl) {
      try {
        response = await fetch(proxyUrl, { credentials: "omit", redirect: "follow" });
      } catch (proxyError) {
        const directDetail = directError instanceof Error ? directError.message : "the browser blocked the request";
        const proxyDetail = proxyError instanceof Error ? proxyError.message : "the local proxy could not be reached";
        throw new Error(`Unable to load ${url}. Direct loading was blocked by CORS (${directDetail}); the local fetch proxy also failed (${proxyDetail}). Paste the page HTML instead.`);
      }
    } else {
      const detail = directError instanceof Error ? directError.message : "the browser blocked the request";
      throw new Error(`Unable to load ${url}. Paste the page HTML instead; direct URL loading requires browser CORS (${detail}).`);
    }
  }
  if (!response.ok) throw new Error(`Unable to load ${url}: the server returned HTTP ${response.status}.`);
  const html = await response.text();
  if (!html.trim()) throw new Error(`Unable to load ${url}: the response did not contain HTML.`);
  const baseUrl = explicitBaseUrl || response.headers.get("X-HTML-Source-URL") || url;

  return {
    html: await inlineSvgImages(html, baseUrl),
    baseUrl,
    sourceUrl: url
  };
}

